    id: 'energetyka-prl',
    title: 'Energetyka PRL',
    subtitle: 'Kraj na węglu',
    category: 'gospodarka',
    tags: ['gospodarka', 'energia', 'przemysł', 'Bełchatów'],
    yearStart: 1945,
