    id: 'arciszewski',
    title: 'Tomasz Arciszewski',
    subtitle: 'Premier rządu, który stracił uznanie',
    category: 'osoby',
    tags: ['emigracja', 'PPS', 'rząd na uchodźstwie', '1945'],
    yearStart: 1944,
